values ((select id from verses where ref='1.46' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'যদি মামপ্রতীকারমশস্ত্রং শস্ত্রপাণযঃ।

ধার্তরাষ্ট্রা রণে হন্যুস্তন্মে ক্ষেমতরং ভবেত্।।1.46।।', null, null, 'published')
