insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='10.3' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'যো মামজমনাদিং চ বেত্তি লোকমহেশ্বরম্।

অসম্মূঢঃ স মর্ত্যেষু সর্বপাপৈঃ প্রমুচ্যতে।।10.3।।', null, null, 'published')
