values ((select id from verses where ref='10.34' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ಮೃತ್ಯುಃ ಸರ್ವಹರಶ್ಚಾಹಮುದ್ಭವಶ್ಚ ಭವಿಷ್ಯತಾಮ್।

ಕೀರ್ತಿಃ ಶ್ರೀರ್ವಾಕ್ಚ ನಾರೀಣಾಂ ಸ್ಮೃತಿರ್ಮೇಧಾ ಧೃತಿಃ ಕ್ಷಮಾ।।10.34।।', null, null, 'published')
