values ((select id from verses where ref='11.47' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-iast'),
        'śrī bhagavānuvāca

mayā prasannena tavārjunedaṃ

rūpaṃ paraṃ darśitamātmayogāt|

tejomayaṃ viśvamanantamādyaṃ

yanme tvadanyena na dṛṣṭapūrvam||11.47||', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.47' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-en-sw'),
        'The Blessed Lord said, "O Arjuna, this Cosmic Form has graciously been shown to you by Me through My own Yogic power. It is full of splendour, primeval, and infinite; this Cosmic Form of Mine has never been seen before by anyone other than you."', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.47' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-mlym'),
        'ശ്രീ ഭഗവാനുവാച

മയാ പ്രസന്നേന തവാർജുനേദം

രൂപം പരം ദർശിതമാത്മയോഗാത്।

തേജോമയം വിശ്വമനന്തമാദ്യം

യന്മേ ത്വദന്യേന ന ദൃഷ്ടപൂർവമ്।।11.47।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.47' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ಶ್ರೀ ಭಗವಾನುವಾಚ

ಮಯಾ ಪ್ರಸನ್ನೇನ ತವಾರ್ಜುನೇದಂ

ರೂಪಂ ಪರಂ ದರ್ಶಿತಮಾತ್ಮಯೋಗಾತ್।

ತೇಜೋಮಯಂ ವಿಶ್ವಮನನ್ತಮಾದ್ಯಂ

ಯನ್ಮೇ ತ್ವದನ್ಯೇನ ನ ದೃಷ್ಟಪೂರ್ವಮ್।।11.47।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.47' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-telu'),
        'శ్రీ భగవానువాచ

మయా ప్రసన్నేన తవార్జునేదం

రూపం పరం దర్శితమాత్మయోగాత్।

తేజోమయం విశ్వమనన్తమాద్యం

యన్మే త్వదన్యేన న దృష్టపూర్వమ్।।11.47।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.47' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'শ্রী ভগবানুবাচ

মযা প্রসন্নেন তবার্জুনেদং

রূপং পরং দর্শিতমাত্মযোগাত্।

তেজোমযং বিশ্বমনন্তমাদ্যং

যন্মে ত্বদন্যেন ন দৃষ্টপূর্বম্।।11.47।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.47' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-gujr'),
        'શ્રી ભગવાનુવાચ

મયા પ્રસન્નેન તવાર્જુનેદં

રૂપં પરં દર્શિતમાત્મયોગાત્।

તેજોમયં વિશ્વમનન્તમાદ્યં

યન્મે ત્વદન્યેન ન દૃષ્ટપૂર્વમ્।।11.47।।', null, null, 'published')
