on conflict (work_id, ref) do update set ordinal=excluded.ordinal, kind=excluded.kind, meter=excluded.meter, speaker_id=excluded.speaker_id, section_id=excluded.section_id, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.50' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-deva'),
        'सञ्जय उवाच

इत्यर्जुनं वासुदेवस्तथोक्त्वा

स्वकं रूपं दर्शयामास भूयः।

आश्वासयामास च भीतमेनं

भूत्वा पुनः सौम्यवपुर्महात्मा।।11.50।।', null, null, 'published')
