insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.50' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-iast'),
        'sañjaya uvāca

ityarjunaṃ vāsudevastathoktvā

svakaṃ rūpaṃ darśayāmāsa bhūyaḥ|

āśvāsayāmāsa ca bhītamenaṃ

bhūtvā punaḥ saumyavapurmahātmā||11.50||', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.50' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-en-sw'),
        'Sanjaya said, Having thus spoken to Arjuna, Krishna again showed His own form. The great Soul, assuming His gentle form, then consoled Arjuna, who was terrified.', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.50' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-mlym'),
        'സഞ്ജയ ഉവാച

ഇത്യർജുനം വാസുദേവസ്തഥോക്ത്വാ

സ്വകം രൂപം ദർശയാമാസ ഭൂയഃ।

ആശ്വാസയാമാസ ച ഭീതമേനം

ഭൂത്വാ പുനഃ സൌമ്യവപുർമഹാത്മാ।।11.50।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.50' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ಸಞ್ಜಯ ಉವಾಚ

ಇತ್ಯರ್ಜುನಂ ವಾಸುದೇವಸ್ತಥೋಕ್ತ್ವಾ

ಸ್ವಕಂ ರೂಪಂ ದರ್ಶಯಾಮಾಸ ಭೂಯಃ।

ಆಶ್ವಾಸಯಾಮಾಸ ಚ ಭೀತಮೇನಂ

ಭೂತ್ವಾ ಪುನಃ ಸೌಮ್ಯವಪುರ್ಮಹಾತ್ಮಾ।।11.50।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.50' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-telu'),
        'సఞ్జయ ఉవాచ

ఇత్యర్జునం వాసుదేవస్తథోక్త్వా

స్వకం రూపం దర్శయామాస భూయః।

ఆశ్వాసయామాస చ భీతమేనం

భూత్వా పునః సౌమ్యవపుర్మహాత్మా।।11.50।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.50' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'সঞ্জয উবাচ

ইত্যর্জুনং বাসুদেবস্তথোক্ত্বা

স্বকং রূপং দর্শযামাস ভূযঃ।

আশ্বাসযামাস চ ভীতমেনং

ভূত্বা পুনঃ সৌম্যবপুর্মহাত্মা।।11.50।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='11.50' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-gujr'),
        'સઞ્જય ઉવાચ

ઇત્યર્જુનં વાસુદેવસ્તથોક્ત્વા

સ્વકં રૂપં દર્શયામાસ ભૂયઃ।

આશ્વાસયામાસ ચ ભીતમેનં

ભૂત્વા પુનઃ સૌમ્યવપુર્મહાત્મા।।11.50।।', null, null, 'published')
