values ((select id from verses where ref='15.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-deva'),
        'ततः पदं तत्परिमार्गितव्य    यस्मिन्गता न निवर्तन्ति भूयः।तमेव चाद्यं पुरुषं प्रपद्ये    यतः प्रवृत्तिः प्रसृता पुराणी।।15.4।।', null, null, 'published')
