values ((select id from verses where ref='15.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-iast'),
        'tataḥ padaṃ tatparimārgitavya    yasmingatā na nivartanti bhūyaḥ|tameva cādyaṃ puruṣaṃ prapadye    yataḥ pravṛttiḥ prasṛtā purāṇī||15.4||', null, null, 'published')
