insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-en-sw'),
        'Then, that goal should be sought for, to which, having gone, none returns again. I seek refuge in that Primeval Purusha, from whence streamed forth the ancient activity or energy.', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-mlym'),
        'തതഃ പദം തത്പരിമാർഗിതവ്യ    യസ്മിന്ഗതാ ന നിവർതന്തി ഭൂയഃ।തമേവ ചാദ്യം പുരുഷം പ്രപദ്യേ    യതഃ പ്രവൃത്തിഃ പ്രസൃതാ പുരാണീ।।15.4।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ತತಃ ಪದಂ ತತ್ಪರಿಮಾರ್ಗಿತವ್ಯ    ಯಸ್ಮಿನ್ಗತಾ ನ ನಿವರ್ತನ್ತಿ ಭೂಯಃ।ತಮೇವ ಚಾದ್ಯಂ ಪುರುಷಂ ಪ್ರಪದ್ಯೇ    ಯತಃ ಪ್ರವೃತ್ತಿಃ ಪ್ರಸೃತಾ ಪುರಾಣೀ।।15.4।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-telu'),
        'తతః పదం తత్పరిమార్గితవ్య    యస్మిన్గతా న నివర్తన్తి భూయః।తమేవ చాద్యం పురుషం ప్రపద్యే    యతః ప్రవృత్తిః ప్రసృతా పురాణీ।।15.4।।', null, null, 'published')
