values ((select id from verses where ref='15.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'ততঃ পদং তত্পরিমার্গিতব্য    যস্মিন্গতা ন নিবর্তন্তি ভূযঃ।তমেব চাদ্যং পুরুষং প্রপদ্যে    যতঃ প্রবৃত্তিঃ প্রসৃতা পুরাণী।।15.4।।', null, null, 'published')
