values ((select id from verses where ref='15.5' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-deva'),
        'निर्मानमोहा जितसङ्गदोषा    अध्यात्मनित्या विनिवृत्तकामाः।द्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञै    र्गच्छन्त्यमूढाः पदमव्ययं तत्।।15.5।।', null, null, 'published')
