insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.5' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-iast'),
        'nirmānamohā jitasaṅgadoṣā    adhyātmanityā vinivṛttakāmāḥ|dvandvairvimuktāḥ sukhaduḥkhasaṃjñai    rgacchantyamūḍhāḥ padamavyayaṃ tat||15.5||', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.5' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-en-sw'),
        'Free from pride and delusion, victorious over the evil of attachment, dwelling constantly in the Self, their desires having completely turned away, freed from the pairs of opposites known as pleasure and pain, they, the undeluded, reach the eternal goal.', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.5' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-mlym'),
        'നിർമാനമോഹാ ജിതസങ്ഗദോഷാ    അധ്യാത്മനിത്യാ വിനിവൃത്തകാമാഃ।ദ്വന്ദ്വൈർവിമുക്താഃ സുഖദുഃഖസംജ്ഞൈ    ർഗച്ഛന്ത്യമൂഢാഃ പദമവ്യയം തത്।।15.5।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.5' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ನಿರ್ಮಾನಮೋಹಾ ಜಿತಸಙ್ಗದೋಷಾ    ಅಧ್ಯಾತ್ಮನಿತ್ಯಾ ವಿನಿವೃತ್ತಕಾಮಾಃ।ದ್ವನ್ದ್ವೈರ್ವಿಮುಕ್ತಾಃ ಸುಖದುಃಖಸಂಜ್ಞೈ    ರ್ಗಚ್ಛನ್ತ್ಯಮೂಢಾಃ ಪದಮವ್ಯಯಂ ತತ್।।15.5।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.5' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-telu'),
        'నిర్మానమోహా జితసఙ్గదోషా    అధ్యాత్మనిత్యా వినివృత్తకామాః।ద్వన్ద్వైర్విముక్తాః సుఖదుఃఖసంజ్ఞై    ర్గచ్ఛన్త్యమూఢాః పదమవ్యయం తత్।।15.5।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.5' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'নির্মানমোহা জিতসঙ্গদোষা    অধ্যাত্মনিত্যা বিনিবৃত্তকামাঃ।দ্বন্দ্বৈর্বিমুক্তাঃ সুখদুঃখসংজ্ঞৈ    র্গচ্ছন্ত্যমূঢাঃ পদমব্যযং তত্।।15.5।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='15.5' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-gujr'),
        'નિર્માનમોહા જિતસઙ્ગદોષા    અધ્યાત્મનિત્યા વિનિવૃત્તકામાઃ।દ્વન્દ્વૈર્વિમુક્તાઃ સુખદુઃખસંજ્ઞૈ    ર્ગચ્છન્ત્યમૂઢાઃ પદમવ્યયં તત્।।15.5।।', null, null, 'published')
