values ((select id from verses where ref='18.40' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-deva'),
        'न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः।सत्त्वं प्रकृतिजैर्मुक्तं यदेभिः स्यात्ित्रभिर्गुणैः।।18.40।।', null, null, 'published')
