insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='18.40' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ನ ತದಸ್ತಿ ಪೃಥಿವ್ಯಾಂ ವಾ ದಿವಿ ದೇವೇಷು ವಾ ಪುನಃ।ಸತ್ತ್ವಂ ಪ್ರಕೃತಿಜೈರ್ಮುಕ್ತಂ ಯದೇಭಿಃ ಸ್ಯಾತ್ಿತ್ರಭಿರ್ಗುಣೈಃ।।18.40।।', null, null, 'published')
