insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='2.6' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-telu'),
        'న చైతద్విద్మః కతరన్నో గరీయో

యద్వా జయేమ యది వా నో జయేయుః।

యానేవ హత్వా న జిజీవిషామ

స్తేఽవస్థితాః ప్రముఖే ధార్తరాష్ట్రాః।।2.6।।', null, null, 'published')
