values ((select id from verses where ref='4.7' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ಯದಾ ಯದಾ ಹಿ ಧರ್ಮಸ್ಯ ಗ್ಲಾನಿರ್ಭವತಿ ಭಾರತ।

