insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='4.7' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'যদা যদা হি ধর্মস্য গ্লানির্ভবতি ভারত।

অভ্যুত্থানমধর্মস্য তদাঽঽত্মানং সৃজাম্যহম্।।4.7।।', null, null, 'published')
