insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='4.9' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-mlym'),
        'ജന്മ കർമ ച മേ ദിവ്യമേവം യോ വേത്തി തത്ത്വതഃ।

ത്യക്ത്വാ ദേഹം പുനർജന്മ നൈതി മാമേതി സോഽർജുന।।4.9।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='4.9' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ಜನ್ಮ ಕರ್ಮ ಚ ಮೇ ದಿವ್ಯಮೇವಂ ಯೋ ವೇತ್ತಿ ತತ್ತ್ವತಃ।

ತ್ಯಕ್ತ್ವಾ ದೇಹಂ ಪುನರ್ಜನ್ಮ ನೈತಿ ಮಾಮೇತಿ ಸೋಽರ್ಜುನ।।4.9।।', null, null, 'published')
