values ((select id from verses where ref='4.32' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ಏವಂ ಬಹುವಿಧಾ ಯಜ್ಞಾ ವಿತತಾ ಬ್ರಹ್ಮಣೋ ಮುಖೇ।

ಕರ್ಮಜಾನ್ವಿದ್ಧಿ ತಾನ್ಸರ್ವಾನೇವಂ ಜ್ಞಾತ್ವಾ ವಿಮೋಕ್ಷ್ಯಸೇ।।4.32।।', null, null, 'published')
