values ((select id from verses where ref='4.32' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'এবং বহুবিধা যজ্ঞা বিততা ব্রহ্মণো মুখে।

কর্মজান্বিদ্ধি তান্সর্বানেবং জ্ঞাত্বা বিমোক্ষ্যসে।।4.32।।', null, null, 'published')
