values ((select id from verses where ref='4.37' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-telu'),
        'యథైధాంసి సమిద్ధోఽగ్నిర్భస్మసాత్కురుతేఽర్జున।

జ్ఞానాగ్నిః సర్వకర్మాణి భస్మసాత్కురుతే తథా।।4.37।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
