values ((select id from verses where ref='4.37' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'যথৈধাংসি সমিদ্ধোঽগ্নির্ভস্মসাত্কুরুতেঽর্জুন।

জ্ঞানাগ্নিঃ সর্বকর্মাণি ভস্মসাত্কুরুতে তথা।।4.37।।', null, null, 'published')
