values ((select id from verses where ref='4.38' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-telu'),
        'న హి జ్ఞానేన సదృశం పవిత్రమిహ విద్యతే।

తత్స్వయం యోగసంసిద్ధః కాలేనాత్మని విన్దతి।।4.38।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='4.38' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'ন হি জ্ঞানেন সদৃশং পবিত্রমিহ বিদ্যতে।

তত্স্বযং যোগসংসিদ্ধঃ কালেনাত্মনি বিন্দতি।।4.38।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
