values ((select id from verses where ref='4.39' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-deva'),
        'श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः।

ज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति।।4.39।।', null, null, 'published')
