values ((select id from verses where ref='4.39' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ಶ್ರದ್ಧಾವಾಁಲ್ಲಭತೇ ಜ್ಞಾನಂ ತತ್ಪರಃ ಸಂಯತೇನ್ದ್ರಿಯಃ।

ಜ್ಞಾನಂ ಲಬ್ಧ್ವಾ ಪರಾಂ ಶಾನ್ತಿಮಚಿರೇಣಾಧಿಗಚ್ಛತಿ।।4.39।।', null, null, 'published')
on conflict (verse_id, edition_id) do update set body=excluded.body, word_meanings=excluded.word_meanings, notes=excluded.notes, status='published';
