values ((select id from verses where ref='8.7' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-beng'),
        'তস্মাত্সর্বেষু কালেষু মামনুস্মর যুধ্য চ।

ময্যর্পিতমনোবুদ্ধির্মামেবৈষ্যস্যসংশযম্।।8.7।।', null, null, 'published')
