values ((select id from verses where ref='8.8' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-mlym'),
        'അഭ്യാസയോഗയുക്തേന ചേതസാ നാന്യഗാമിനാ।

