values ((select id from verses where ref='9.2' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-mlym'),
        'രാജവിദ്യാ രാജഗുഹ്യം പവിത്രമിദമുത്തമമ്।

