values ((select id from verses where ref='9.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-knda'),
        'ಮಯಾ ತತಮಿದಂ ಸರ್ವಂ ಜಗದವ್ಯಕ್ತಮೂರ್ತಿನಾ।

ಮತ್ಸ್ಥಾನಿ ಸರ್ವಭೂತಾನಿ ನ ಚಾಹಂ ತೇಷ್ವವಸ್ಥಿತಃ।।9.4।।', null, null, 'published')
