insert into verse_contents (verse_id, edition_id, body, word_meanings, notes, status)
values ((select id from verses where ref='9.4' and work_id=(select id from works where slug='bhagavad-gita')), (select id from editions where slug='bg-mula-telu'),
        'మయా తతమిదం సర్వం జగదవ్యక్తమూర్తినా।

మత్స్థాని సర్వభూతాని న చాహం తేష్వవస్థితః।।9.4।।', null, null, 'published')
